<?php defined('BASEPATH') OR exit('No direct script access allowed'); ?>
<?php $types=array();$regions=array();foreach($projects as$p){if($p->project_type)$types[$p->project_type]=$p->project_type;if($p->region)$regions[$p->region]=$p->region;}ksort($types);ksort($regions);?>
<?php if($this->session->flashdata('project_success')):?><div class="alert alert-success"><?=html_escape($this->session->flashdata('project_success'))?></div><?php endif;?>
<div class="card shadow-sm mb-3"><div class="card-body"><div class="row g-3 align-items-end"><div class="col-md-3"><label class="form-label" for="project-type-filter">Project type</label><select class="form-select" id="project-type-filter" data-master-filter data-table-target="project-table" data-column="2"><option value="">All types</option><?php foreach($types as$v):?><option><?=html_escape($v)?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label" for="project-region-filter">Region</label><select class="form-select" id="project-region-filter" data-master-filter data-table-target="project-table" data-column="4"><option value="">All regions</option><?php foreach($regions as$v):?><option><?=html_escape($v)?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label" for="project-status-filter">Status</label><select class="form-select" id="project-status-filter" data-master-filter data-table-target="project-table" data-column="8"><option value="">All statuses</option><option>Active</option><option>Inactive</option></select></div><div class="col-md-3"><?php if($can_manage):?><a class="btn btn-primary w-100" href="<?=site_url('projects/create')?>"><i class="bi bi-plus-lg"></i> Add Project</a><?php endif;?></div></div></div></div>
<div class="card shadow-sm"><div class="card-body"><div class="table-responsive"><table id="project-table" class="table table-striped table-hover align-middle w-100 master-data-table"><thead><tr><th>Code</th><th>Project</th><th>Type</th><th>Building</th><th>Region</th><th>Location</th><th>Period</th><th>Rate Observations</th><th>Status</th><th data-dt-order="disable">Actions</th></tr></thead><tbody><?php foreach($projects as$p):?><tr><td><a class="fw-semibold text-decoration-none" href="<?=site_url('projects/'.$p->project_id)?>"><?=html_escape($p->project_code)?></a></td><td><?=html_escape($p->project_name)?></td><td><?=html_escape($p->project_type?:'—')?></td><td><?=html_escape($p->building_type?:'—')?></td><td><?=html_escape($p->region?:'—')?></td><td><?=html_escape(implode(', ',array_filter(array($p->city,$p->province,$p->country))))?></td><td><?=$p->start_date?html_escape(date('d-M-Y',strtotime($p->start_date))):'—'?> – <?=$p->completion_date?html_escape(date('d-M-Y',strtotime($p->completion_date))):'—'?></td><td><?=number_format($p->observation_count)?></td><td><span class="badge text-bg-<?=$p->is_active?'success':'secondary'?>"><?=$p->is_active?'Active':'Inactive'?></span></td><td class="text-nowrap"><a class="btn btn-outline-secondary btn-sm" href="<?=site_url('projects/'.$p->project_id)?>"><i class="bi bi-eye"></i></a><?php if($can_manage):?> <a class="btn btn-outline-primary btn-sm" href="<?=site_url('projects/'.$p->project_id.'/edit')?>"><i class="bi bi-pencil"></i></a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div>
